    "short": "蜀汉名将，与刘备、张飞桃园结义。勇武绝伦，威震华夏，后被孙权部将吕蒙所杀。",
    "intro": "关羽，字云长，河东解人也。据《三国志·蜀书·关羽传》，关羽字云长，本字长生，河东解人也。亡命奔涿郡。先主于乡里合徒众，而羽与张飞为之御侮。先主为平原相，以羽、飞为别部司马，分统部曲。先主与二人寝则同床，恩若兄弟。而稠人广坐，侍立终日，随先主周旋，不避艰险。先主之袭杀徐州刺史车胄，使羽守下邳城，行太守事，而身还小沛。建安五年，曹公东征，先主奔袁绍。曹公禽羽以归，拜为偏将军，礼之甚厚。绍遣大将颜良攻东郡太守刘延于白马，曹公使张辽及羽为先锋击之。羽望见良麾盖，策马刺良于万众之中，斩其首还，绍诸将莫能当者，遂解白马围。曹公即表封羽为汉寿亭侯。初，曹公壮羽为人，而察其心神无久留之意，谓张辽曰：「卿试以情问之。」既而辽以问羽，羽叹曰：「吾极知曹公待我厚，然吾受刘将军厚恩，誓以共死，不可背之。吾终不留，吾要当立效以报曹公乃去。」辽以羽言报曹公，曹公义之。及羽杀颜良，曹公知其必去，重加赏赐。羽尽封其所赐，拜书告辞，而奔先主于袁军。左右欲追之，曹公曰：「彼各为其主，勿追也。」从先主就刘表。表卒，曹公定荆州，先主自樊将南渡江，别遣羽乘船数百艘会江陵。曹公追至当阳长坂，先主斜趣汉津，适与羽船相值，共至夏口。孙权遣兵佐先主拒曹公，曹公引军退归。先主收江南诸郡，乃封拜元勋，以羽为襄阳太守、荡寇将军，驻江北。先主西定益州，拜羽董督荆州事。羽闻马超来降，旧非故人，羽书与诸葛亮，问超人才可谁比类。亮知羽护前，乃答之曰：「孟起兼资文武，雄烈过人，一世之杰，黥、彭之徒，当与益德并驱争先，犹未及髯之绝伦逸群也。」羽美须髯，故亮谓之髯。羽省书大悦，以示宾客。羽尝为流矢所中，贯其左臂，后创虽愈，每至阴雨，骨常疼痛，医曰：「矢镞有毒，毒入于骨，当破臂作创，刮骨去毒，然后此患乃除耳。」羽便伸臂令医劈之。时羽适请诸将饮食相对，臂血流离，盈于盘器，而羽割炙引酒，言笑自若。二十四年，先主为汉中王，拜羽为前将军，假节钺。是岁，羽率众攻曹仁于樊。曹公遣于禁助仁。秋，大霖雨，汉水汎溢，禁所督七军皆没。禁降羽，羽又斩将军庞德。梁、郏、陆浑群盗或遥受羽印号，为之支党，羽威震华夏。曹公议徙许都以避其锐，司马宣王、蒋济以为关羽得志，孙权必不愿也。可遣人劝权蹑其后，许割江南以封权，则樊围自解。曹公从之。初，曹公壮羽为人，而察其心神无久留之意，谓张辽曰：「卿试以情问之。」既而辽以问羽，羽叹曰：「吾极知曹公待我厚，然吾受刘将军厚恩，誓以共死，不可背之。吾终不留，吾要当立效以报曹公乃去。」辽以羽言报曹公，曹公义之。及羽杀颜良，曹公知其必去，重加赏赐。羽尽封其所赐，拜书告辞，而奔先主于袁军。左右欲追之，曹公曰：「彼各为其主，勿追也。」从先主就刘表。表卒，曹公定荆州，先主自樊将南渡江，别遣羽乘船数百艘会江陵。曹公追至当阳长坂，先主斜趣汉津，适与羽船相值，共至夏口。孙权遣兵佐先主拒曹公，曹公引军退归。先主收江南诸郡，乃封拜元勋，以羽为襄阳太守、荡寇将军，驻江北。先主西定益州，拜羽董督荆州事。羽闻马超来降，旧非故人，羽书与诸葛亮，问超人才可谁比类。亮知羽护前，乃答之曰：「孟起兼资文武，雄烈过人，一世之杰，黥、彭之徒，当与益德并驱争先，犹未及髯之绝伦逸群也。」羽美须髯，故亮谓之髯。羽省书大悦，以示宾客。羽尝为流矢所中，贯其左臂，后创虽愈，每至阴雨，骨常疼痛，医曰：「矢镞有毒，毒入于骨，当破臂作创，刮骨去毒，然后此患乃除耳。」羽便伸臂令医劈之。时羽适请诸将饮食相对，臂血流离，盈于盘器，而羽割炙引酒，言笑自若。二十四年，先主为汉中王，拜羽为前将军，假节钺。是岁，羽率众攻曹仁于樊。曹公遣于禁助仁。秋，大霖雨，汉水汎溢，禁所督七军皆没。禁降羽，羽又斩将军庞德。梁、郏、陆浑群盗或遥受羽印号，为之支党，羽威震华夏。曹公议徙许都以避其锐，司马宣王、蒋济以为关羽得志，孙权必不愿也。可遣人劝权蹑其后，许割江南以封权，则樊围自解。曹公从之。",
