    "controversy": "炎帝与神农氏是否为同一人，学界有争议。部分学者认为炎帝是姜姓部落首领的称号，而非具体个人。",
    "quote": "炎帝神农氏，姜姓也。母曰任姒，有蟜氏之女，名曰女登，为少典妃。游于华阳，有神龙首感女登于常羊，生炎帝。",
