    "short": "夏朝开国君主，以治水闻名。三过家门而不入，十三年治水功成，受舜禅让建立夏朝。",
    "intro": "禹，姒姓，夏后氏，名文命。据《史记·夏本纪》，禹之父曰鲧，鲧之父曰帝颛顼。禹乃舜所荐，以治水。禹为人，敏给克勤；其德不违，其仁可亲，其言可信；声为律，身为度，称以出。禹伤先人父鲧功之不成受诛，乃劳身焦思，居外十三年，过家门不敢入。薄衣食，致孝于鬼神；卑宫室，致费于沟淢。陆行乘车，水行乘船，泥行乘橇，山行乘檋。左准绳，右规矩，载四时，以开九州，通九道，陂九泽，度九山。",
