    "short": "春秋时期吴国大夫，因楚平王杀其父兄，逃亡吴国，辅佐吴王阖闾攻破楚都，鞭尸楚平王。",
    "intro": "伍子胥，楚国人，名员。据《史记·伍子胥列传》，伍子胥父伍奢，为楚平王太子建太傅。平王听信费无忌谗言，杀伍奢及伍子胥兄伍尚。伍子胥逃亡吴国，历经艰险。后辅佐吴王阖闾，推荐孙武。吴国攻破楚都郢，伍子胥掘楚平王墓，鞭其尸三百。吴王夫差继位后，伍子胥劝夫差灭越，夫差不听。夫差伐齐，伍子胥谏曰：「越在，心腹疾，而王不先，而谋齐，不亦谬乎！」夫差不听。太宰嚭受越贿赂，谗伍子胥。夫差赐伍子胥属镂之剑，曰：「子以此死。」伍子胥仰天叹曰：「嗟乎！谗臣嚭为乱矣，王乃反诛我。我令若父霸。自若未立时，诸公子争立，我以死争之於先王，几不得立。若既得立，欲分吴国予我，我顾不敢望也。然今若听谀臣言以杀长者。」乃告其舍人曰：「必树吾墓上以梓，令可以为器；而抉吾眼县吴东门之上，以观越寇之入灭吴也。」乃自刭死。",
    "achievements": [
      "辅佐吴王阖闾称霸",
      "推荐孙武于吴王",
      "攻破楚都郢，鞭尸楚平王",
      "预见越国将灭吴"
    ],
    "controversy": "伍子胥掘墓鞭尸，被孔子批评为「不忠」；但后世多同情其遭遇。",
    "quote": "抉吾眼县吴东门之上，以观越寇之入灭吴也。",
    "quoteSrc": "《史记·伍子胥列传》",
