    "short": "战国四公子之一，魏昭王少子。窃符救赵，威震天下，为后世称颂。",
    "intro": "信陵君，魏无忌者，魏昭王少子而魏安釐王异母弟也。据《史记·魏公子列传》，公子为人仁而下士，士无贤不肖皆谦而礼交之，不敢以其富贵骄士。士以此方数千里争往归之，致食客三千人。当是时，诸侯以公子贤，多客，不敢加兵谋魏十馀年。秦兵围邯郸，赵平原君求救于魏。魏王使将军晋鄙将十万众救赵。秦王使使者告魏王曰：「吾攻赵旦暮且下，而诸侯敢救者，已拔赵，必移兵先击之。」魏王恐，使人止晋鄙，留军壁邺，名为救赵，实持两端以观望。平原君使者冠盖相属于魏，让魏公子曰：「胜所以自附为婚姻者，以公子之高义，为能急人之困。今邯郸旦暮降秦而魏救不至，安在公子能急人之困也！」公子患之，数请魏王，及宾客辩士说王万端。魏王畏秦，终不听公子。公子自度终不能得之於王，计不独生而令赵亡，乃请宾客，约车骑百馀乘，欲以客往赴秦军，与赵俱死。行过夷门，见侯生，具告所以欲死秦军状。侯生曰：「公子喜士，名闻天下。今有难，无他端而欲赴秦军，譬若以肉投馁虎，何功之有哉？尚安事客？然公子遇臣厚，公子往而臣不送，以是知公子恨之复返也。」公子再拜，因问。侯生乃屏人间语，曰：「嬴闻晋鄙之兵符常在王卧内，而如姬最幸，出入王卧内，力能窃之。嬴闻如姬父为人所杀，如姬资之三年，自王以下欲求报其父仇，莫能得。如姬为公子泣，公子使客斩其仇头，敬进如姬。如姬之欲为公子死，无所辞，顾未有路耳。公子诚一开口请如姬，如姬必许诺，则得虎符夺晋鄙军，北救赵而西却秦，此五霸之伐也。」公子从其计，请如姬。如姬果盗晋鄙兵符与公子。",
    "achievements": [
      "战国四公子之首",
      "食客三千人",
      "窃符救赵，威震天下",
      "为后世称颂的贤公子"
    ],
    "controversy": "信陵君窃符救赵，虽救赵成功，但触犯魏王，终不能复用於魏。",
