    "intro": "蔺相如者，赵人也，为赵宦者令缪贤舍人。据《史记·廉颇蔺相如列传》，赵惠文王时，得楚和氏璧。秦昭王闻之，使人遗赵王书，愿以十五城请易璧。蔺相如自愿奉璧使秦，完璧归赵。后秦赵会于渑池，蔺相如随行，以智维护赵国尊严。拜为上卿，位在廉颇之右。廉颇不服，宣言曰：「我见相如，必辱之。」相如闻，不肯与会。相如每朝时，常称病，不欲与廉颇争列。已而相如出，望见廉颇，相如引车避匿。於是舍人相与谏曰：「臣所以去亲戚而事君者，徒慕君之高义也。今君与廉颇同列，廉君宣恶言而君畏匿之，恐惧殊甚，且庸人尚羞之，况於将相乎！臣等不肖，请辞去。」蔺相如固止之，曰：「公之视廉将军孰与秦王？」曰：「不若也。」相如曰：「夫以秦王之威，而相如廷叱之，辱其群臣，相如虽驽，独畏廉将军哉？顾吾念之，强秦之所以不敢加兵於赵者，徒以吾两人在也。今两虎共斗，其势不俱生。吾所以为此者，以先国家之急而後私仇也。」廉颇闻之，肉袒负荆，因宾客至蔺相如门谢罪。曰：「鄙贱之人，不知将军宽之至此也。」卒相与欢，为刎颈之交。",
    "achievements": [
      "完璧归赵",
      "渑池之会维护赵国尊严",
      "与廉颇将相和",
      "以先国家之急而後私仇"
    ],
    "controversy": "蔺相如出身卑微，仅靠一次外交成功即拜上卿，位在廉颇之右，引起廉颇不满。",
    "quote": "吾所以为此者，以先国家之急而後私仇也。",
    "quoteSrc": "《史记·廉颇蔺相如列传》",
