    "short": "汉初三杰之一，刘邦的丞相。镇国家抚百姓，给饷馈不绝粮道，为刘邦建立汉朝立下汗马功劳。",
    "intro": "萧何，沛丰人。据《史记·萧相国世家》，萧何以文无害为沛主吏掾。高祖为布衣时，何数以吏事护高祖。高祖为亭长，常左右之。及高祖起为沛公，何常为丞督事。沛公至咸阳，诸将皆争走金帛财物之府分之，何独先入收秦丞相御史律令图书藏之。沛公为汉王，以何为丞相。楚汉战争时，何镇关中，抚百姓，给饷馈，不绝粮道。汉兴，何定律令，制礼仪，为汉初制度奠基。",
    "achievements": [
      "收秦图书律令，为刘邦了解天下地形户口",
      "镇关中，抚百姓，给饷馈，不绝粮道",
      "定律令，制礼仪，为汉初制度奠基",
      "举荐韩信，为刘邦取得大将"
    ],
    "controversy": "萧何晚年自污以求自保，被刘邦下狱；韩信被诛后，萧何被刘邦加封，百姓谓之「成也萧何，败也萧何」。",
    "quote": "镇国家，抚百姓，给饷馈，不绝粮道。",
