    "short": "中国历史上第一位皇帝，统一六国，建立中央集权制度。",
    "intro": "秦始皇嬴政，秦庄襄王之子。前246年即位，前230—前221年先后灭韩、赵、魏、楚、燕、齐六国，完成统一大业。自称「始皇帝」，推行郡县制、书同文、车同轨、统一度量衡，修筑长城与驰道。晚年求仙问道，焚书坑儒，滥用民力。前210年东巡途中病逝于沙丘。",
