    "short": "汉武帝时期大将军，平阳侯，皇后卫子夫之弟。七次出击匈奴，收复河套，为汉朝解除北方边患。",
    "intro": "卫青，字仲卿，河东平阳人。据《史记·卫将军骠骑列传》，卫青出身卑微，少时为平阳侯家骑奴。其姊卫子夫得幸于武帝，卫青因此入宫。后击匈奴有功，拜为大将军，封长平侯。卫青一生七次出击匈奴，收复河套地区，设朔方郡，解除了匈奴对长安的直接威胁。卫青为人仁善退让，以和柔自媚于上，然天下未有称也。",
    "achievements": [
      "七次出击匈奴，收复河套",
      "拜为大将军，封长平侯",
      "为人仁善退让，得将士之心",
      "解除匈奴对长安的直接威胁"
    ],
    "controversy": "卫青因外戚身份得势，部分史家认为其成功与汉武帝对卫子夫的宠幸有关。",
    "quote": "大将军青为人仁善退让，以和柔自媚于上，然天下未有称也。",
