    "intro": "霍去病，河东平阳人，卫青之甥。据《史记·卫将军骠骑列传》，霍去病年十八为侍中。善骑射，再从大将军，为票姚校尉。元狩二年，霍去病为骠骑将军，将万骑出陇西，击匈奴，过焉支山千余里，杀折兰王，斩卢胡王，执浑邪王子及相国、都尉，首虏八千余级。元狩四年，霍去病出代郡，封狼居胥山，禅于姑衍，登临翰海。",
