    "intro": "张骞，汉中成固人。据《史记·大宛列传》，张骞以郎应募，使月氏。行时百余，去十三岁，唯二人得还。匈奴留骞十余岁，与胡妻，有子，然骞持汉节不失。后骞从大将军击匈奴，知水草处，军得以不乏，乃封骞为博望侯。骞身所至者大宛、大月氏、大夏、康居，而传闻其旁大国五六，具为天子言之。",
