    "short": "东汉开国名将，云台二十八将之一。善用兵法，攻城略地，未尝挫折。",
    "intro": "耿弇，字伯昭，扶风郡茂陵人也。据《后汉书·耿弇传》，其先武帝时以吏二千石自巨鹿徙焉。父况，字侠游，以明经为郎，与王莽从弟伋共学老子于安丘先生，后为朔调连率。弇少好学，习父业。常见郡尉试骑士，建旗鼓，肄驰射，由是好将帅之事。及王莽败，更始立，诸将略地者，前后多拥众。弇时从父在朝，闻光武在卢奴，乃驰北上谒，光武留署门下吏。弇因说护军朱祐，求发兵。光武乃拜况为大将军，弇为偏将军。及更始败，光武即位，拜弇为建威大将军。弇凡所平郡四十六，屠城三百，未尝挫折。建武十三年，增弇户邑。每有四方异议，辄召入问筹策。",
