    "intro": "许慎，字叔重，汝南郡召陵人也。据《后汉书·儒林列传》，性淳笃，少博学经籍，马融常推敬之，时人为之语曰：「五经无双许叔重。」为郡功曹，举孝廉，再迁除洨长。后举为太尉南阁祭酒。尝从贾逵受古学，博通经籍。时人谓之「五经无双」。慎以五经传说臧否不同，于是撰为《五经异义》。又作《说文解字》十四篇，皆传于世。",
