    "short": "西汉外戚，篡汉建立新朝，推行托古改制，引发天下大乱，最终被杀。",
    "intro": "王莽者，字巨君，魏郡元城人也。据《汉书·王莽传》，王莽姑母为汉元帝皇后，成帝太后。莽少孤，折节为恭俭，勤身博学，被服如儒生。事母及寡嫂，养孤兄子，行甚敕备。又外交英俊，内事诸父，曲有礼意。阳朔中，世父大将军凤病，莽侍疾，亲尝药，乱首垢面，不解衣带连月。凤且死，以托太后及帝，拜为黄门郎，迁射声校尉。久之，叔父成都侯商上书，愿分户邑以封莽。及长乐少府戴崇、侍中金涉、胡骑校尉箕闳、上谷都尉阳并、中郎陈汤，皆当世名士，咸为莽言，上由是贤莽。永始元年，封莽为新都侯，国南阳新野之都乡，千五百户。迁骑都尉、光禄大夫、侍中。宿卫谨敕，爵位益尊，节操愈谦。散舆马衣裘，振施宾客，家无所馀。收赡名士，交结将相、卿、大夫甚众。故在位更推荐之，游者为之谈说，虚誉隆洽，倾其诸父矣。莽为曲阳侯根为大司马辅政，荐莽自代。根因乞骸骨，荐莽自代，上遂擢为大司马。是岁，绥和元年也，年三十八矣。莽既拔出同列，继四父而辅政，欲令名誉过前人，遂克己不倦，聘诸贤良以为掾史，赏赐邑钱悉以享士，愈为俭约。母病，公卿列侯遣夫人问疾，莽妻迎之，衣不曳地，布蔽膝，见之者以为僮使，问知其夫人，皆惊。辅政岁馀，成帝崩，哀帝即位，莽避帝外家，就国。哀帝崩，无子，太后诏莽为大司马，与议立嗣。莽白以太后命，立中山王为帝，是为平帝。平帝年九岁，太后临朝称制，委政于莽。元始元年，王莽加号安汉公。五年，平帝崩，莽立宣帝玄孙婴为帝，年三岁，号曰孺子。莽居摄，称假皇帝。居摄三年，即真天子位，定有天下之号曰新。",
