    "short": "尧禅让帝位于舜，舜禅让帝位于禹，是中国上古传说中禅让制的典范。",
    "bg": "尧年老时，问四岳谁能继位。四岳皆推荐舜。尧乃以二女妻舜，以观其内；使九男与处，以观其外。舜举用八恺八元，流放四凶。尧崩后，舜继位。舜年老时，又禅让于禹。",
    "process": "尧禅让于舜，舜举用八恺八元，流放四凶。舜禅让于禹，禹治水十三年功成。",
    "result": "禅让制确立了「选贤与能」的治国理想，成为后世儒家政治理想的重要来源。",
