    "process": "谢玄遣使谓苻坚曰：「君悬军深入，而置阵逼水，此不可久，愿君少却，令将士得周旋，仆与诸君缓辔而观之，不亦乐乎！」坚众皆曰：「宜阻淝水，莫令得上。」坚曰：「但却军，令得过，而我以铁骑数十万向水，逼而杀之。」融亦以为然，遂麾使却阵，众因乱不能止。于是玄与琰、伊等以精锐八千涉渡淝水，坚众奔溃，自相蹈藉，投水死者不可胜计，淝水为之不流。",
